-- Ebene Stadt/Gemeinde nach dem Kreis: NRW → Regierungsbezirk → Kreis → Gemeinde → Schule.
-- * schools.gemeinde_id (AGS, 8-stellig) aus den amtlichen Gemeindegrenzen (scripts/assign-gemeinden.ts).
-- * Alle Aggregat-RPCs kennen level 'gemeinde' (parentId = Kreis); Schul-Abfragen nehmen als parentId einen
--   Kreis (5-stellig) oder eine Gemeinde (8-stellig). Rechenlogik unverändert, nur die Gruppierung ist neu.

alter table public.schools
  add column gemeinde_id text check (gemeinde_id ~ '^05[0-9]{6}$' or is_test);
create index schools_gemeinde_id_idx on public.schools (gemeinde_id);
grant select (gemeinde_id) on public.schools to anon, authenticated;

-- Bestehende echte Schulen (Schulverzeichnis NRW). Neue oder synthetische kommen über den Seed.
update public.schools s set gemeinde_id = v.gemeinde_id
