-- Elternregion einer Schule auf der Ebene unterhalb von `level`: Kreis-ID für Gemeinden, für Schulen je nach
-- Länge des parentId Kreis (5) oder Gemeinde (8), sonst der Regierungsbezirk.
create function public.parent_of(level text, parent text, kreis_id text, gemeinde_id text) returns text
  language sql
  immutable
as $$
  select case
    when level = 'gemeinde' then kreis_id
    when level = 'school' and length(parent) = 8 then gemeinde_id
    when level = 'school' then kreis_id
    else left(kreis_id, 3)
  end
$$;
revoke execute on function public.parent_of(text, text, text, text) from public, anon, authenticated;

create or replace function public.assert_public_level(query jsonb) returns void
  language plpgsql immutable set search_path = '' as $$
begin
  if query ->> 'level' is null or query ->> 'level' not in ('nrw', 'regbez', 'kreis', 'gemeinde', 'school') then
    raise exception 'level must be nrw, regbez, kreis, gemeinde or school' using errcode = '22023';
  end if;
end;
$$;

alter table private.imported_aggregates drop constraint imported_aggregates_level_check,
  add constraint imported_aggregates_level_check check (level in ('nrw', 'regbez', 'kreis', 'gemeinde', 'school'));

create or replace function public.rollup_aggregate_rows(query jsonb, wave_ids text[], previous_wave_ids text[])
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = ''
as $$
declare
  v_level text := query ->> 'level';
  v_topic text := query ->> 'topic';
  v_role text := query ->> 'role';
  v_parent text := query ->> 'parentId';
  v_forms text[] := public.jsonb_text_array(query, 'schoolForm');
  v_bands text[] := public.jsonb_text_array(query, 'gradeBand');
  v_k integer := public.k_min();
  v_source text;
  v_rows jsonb;
begin
  if v_level is null or v_level not in ('nrw', 'regbez', 'kreis', 'gemeinde', 'school', 'pitch') then
    raise exception 'level must be nrw, regbez, kreis, gemeinde or school' using errcode = '22023';
  end if;
  if v_topic is null then
    raise exception 'topic is required (slug or "all")' using errcode = '22023';
  end if;
  if v_role is not null and v_role not in ('student', 'teacher') then
    raise exception 'invalid role' using errcode = '22023';
  end if;
  v_source := case when v_level = 'pitch' then null else public.resolve_source(query) end;

  with selected_schools as (
    select
      s.id,
      case v_level when 'pitch' then s.id when 'school' then s.id when 'gemeinde' then s.gemeinde_id
        when 'kreis' then s.kreis_id when 'nrw' then 'nrw' else left(s.kreis_id, 3) end as group_id
    from public.schools s
    where ((v_level = 'pitch' and s.is_test and s.id = 'pitch-test')
        or (v_level <> 'pitch' and not s.is_test))
      and (cardinality(v_forms) = 0 or s.school_form = any (v_forms))
      and (v_level <> 'gemeinde' or s.gemeinde_id is not null)
      and (v_level = 'nrw' or v_parent is null or public.parent_of(v_level, v_parent, s.kreis_id, s.gemeinde_id) = v_parent)
  ),
  -- Additive cells per group, period and topic ('*' = whole responses).
  cells as (
    select
      ss.group_id,
      rr.wave_id = any (wave_ids) as is_current,
      rr.topic_slug,
      sum(rr.answered) as answered,
      sum(rr.counted) as counted,
      sum(rr.sum_pw) as sum_pw,
      sum(rr.sum_w) as sum_w,
      sum(rr.d1) as d1, sum(rr.d2) as d2, sum(rr.d3) as d3, sum(rr.d4) as d4, sum(rr.d5) as d5
    from selected_schools ss
    join private.response_rollup rr on rr.school_id = ss.id
    where (v_source is null or rr.source_id = v_source)
      and (rr.wave_id = any (wave_ids) or rr.wave_id = any (previous_wave_ids))
      and (v_role is null or rr.role = v_role)
      and (cardinality(v_bands) = 0 or rr.grade_band = any (v_bands))
    group by 1, 2, 3
  ),
  -- topicScore(): n = distinct responses with a scored answer; weighted mean; null below K_MIN.
  -- topicScores list every topic answered in the cell, also choice-only ones (→ null).
  topic_scores as (
    select
      group_id,
      is_current,
      topic_slug,
      counted as n,
      case when counted < v_k then null else public.round1(sum_pw / sum_w) end as score
    from cells
    where topic_slug <> '*' and answered > 0
  ),
  -- Overall mood: distinct responses over all topics; overallScore() = mean in whole tenths.
  period_overall as (
    select group_id, is_current, floor(sum(floor(score * 10 + 0.5)) / count(*) + 0.5) / 10 as overall
    from topic_scores
    where score is not null
    group by group_id, is_current
  ),
  period_totals as (
    select c.group_id, c.is_current, c.counted as n, o.overall
    from cells c
    left join period_overall o using (group_id, is_current)
    where c.topic_slug = '*'
  ),
  -- Real mood5 distribution for the selected topic (#222).
  distribution_json as (
    select
      group_id,
      jsonb_build_object('1', d1, '2', d2, '3', d3, '4', d4, '5', d5) as distribution
    from cells
    where is_current and topic_slug = v_topic and v_topic <> '*'
  ),
  topic_json as (
    select group_id, jsonb_object_agg(topic_slug, score) as scores
    from topic_scores
    where is_current
    group by group_id
  ),
  periods as (
    select g.group_id, p.is_current
    from (select distinct group_id from selected_schools) g
    cross join (values (true), (false)) as p (is_current)
  ),
  totals as (
    select
      p.group_id,
      p.is_current,
      case when v_topic = 'all' then coalesce(pt.n, 0) else coalesce(ts.n, 0) end as n,
      case
        when v_topic = 'all' then case when coalesce(pt.n, 0) < v_k then null else pt.overall end
        else ts.score
      end as score
    from periods p
    left join period_totals pt on pt.group_id = p.group_id and pt.is_current = p.is_current
    left join topic_scores ts on ts.group_id = p.group_id and ts.is_current = p.is_current and ts.topic_slug = v_topic
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', cur.group_id,
        'n', cur.n,
        'score', cur.score,
        -- delta(): only when both periods reach K_MIN and have a score.
        'delta', case
          when cur.n >= v_k and prev.n >= v_k and cur.score is not null and prev.score is not null
          then public.round1(cur.score - prev.score)
        end,
        'topicScores', coalesce(tj.scores, '{}'::jsonb)
      ) || case
        when v_topic = 'all' then '{}'::jsonb
        else jsonb_build_object(
          'distribution',
          case when cur.n >= v_k then dj.distribution end
        )
      end
      order by cur.group_id collate "C"
    ),
    '[]'::jsonb
  )
  into v_rows
  from totals cur
  join totals prev on prev.group_id = cur.group_id and not prev.is_current
  left join topic_json tj on tj.group_id = cur.group_id
  left join distribution_json dj on dj.group_id = cur.group_id
  where cur.is_current
    -- School rows without any scored answers are omitted (#219); other levels keep their empty rows.
    and (v_level <> 'school' or cur.n > 0);

  return v_rows;
end;
$$;

create or replace function public.provider_aggregate_rows(
  query jsonb, wave_ids text[], previous_wave_ids text[], source_id text
) returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = ''
as $$
declare
  v_level text := query ->> 'level';
  v_topic text := query ->> 'topic';
  v_parent text := query ->> 'parentId';
  v_k integer := public.k_min();
  v_filtered boolean := cardinality(public.jsonb_text_array(query, 'schoolForm')) > 0
    or cardinality(public.jsonb_text_array(query, 'gradeBand')) > 0
    or query ->> 'role' is not null;
  v_rows jsonb;
begin
  with groups as (
    select distinct
      case v_level when 'nrw' then 'nrw' when 'regbez' then left(s.kreis_id, 3) when 'kreis' then s.kreis_id
        when 'gemeinde' then s.gemeinde_id else s.id end as id
    from public.schools s
    where not s.is_test
      and (v_level <> 'gemeinde' or s.gemeinde_id is not null)
      and (v_level = 'nrw' or v_parent is null
        or public.parent_of(v_level, v_parent, s.kreis_id, s.gemeinde_id) = v_parent)
  ),
  cells as (
    select g.region_id, g.topic, g.wave_id, g.n, g.score, g.distribution,
      g.wave_id = any (wave_ids) as is_current
    from private.imported_aggregates g
    where g.source_id = provider_aggregate_rows.source_id and g.level = v_level and not v_filtered
      and (g.wave_id = any (wave_ids) or g.wave_id = any (previous_wave_ids))
  ),
  -- One delivered wave per period, otherwise the period has no value.
  picked as (
    select region_id, topic, is_current, min(n) as n,
      case when min(n) < v_k then null else min(score) end as score,
      case when min(n) < v_k then null else (array_agg(distribution))[1] end as distribution
    from cells
    group by region_id, topic, is_current
    having count(*) = 1
  )
  select coalesce(jsonb_agg(row_json order by id collate "C"), '[]'::jsonb) into v_rows
  from (
    select g.id,
      jsonb_build_object(
        'id', g.id,
        'n', coalesce(cur.n, 0),
        'score', cur.score,
        'delta', case when cur.score is not null and prev.score is not null
          then public.round1(cur.score - prev.score) end,
        'topicScores', coalesce((
          select jsonb_object_agg(t.topic, t.score) from picked t
          where t.region_id = g.id and t.is_current and t.topic <> 'all'
        ), '{}'::jsonb)
      ) || case when v_topic = 'all' then '{}'::jsonb
        else jsonb_build_object('distribution', cur.distribution) end as row_json,
      coalesce(cur.n, 0) as n
    from groups g
    left join picked cur on cur.region_id = g.id and cur.topic = v_topic and cur.is_current
    left join picked prev on prev.region_id = g.id and prev.topic = v_topic and not prev.is_current
  ) r
  -- Like the rollup path: school rows without data are omitted.
  where v_level <> 'school' or r.n > 0;
  return v_rows;
end;
$$;

create or replace function public.aggregate_rows(query jsonb, wave_ids text[], previous_wave_ids text[])
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = ''
as $$
declare
  v_source text;
begin
  if query ->> 'level' is distinct from 'pitch' then
    v_source := public.resolve_source(query);
    if exists (select 1 from public.data_sources where id = v_source and aggregated_by_provider) then
      if query ->> 'level' not in ('nrw', 'regbez', 'kreis', 'gemeinde', 'school') or query ->> 'topic' is null then
        raise exception 'level must be nrw, regbez, kreis, gemeinde or school' using errcode = '22023';
      end if;
      return public.provider_aggregate_rows(query, wave_ids, previous_wave_ids, v_source);
    end if;
  end if;
  return public.rollup_aggregate_rows(query, wave_ids, previous_wave_ids);
end;
$$;

create or replace function public.choice_distribution(question_id text, scope jsonb, wave_id text) returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = ''
as $$
declare
  v_level text := scope ->> 'level';
  v_id text := scope ->> 'id';
  v_source text;
  q public.questions%rowtype;
  v_n integer;
  v_result jsonb;
begin
  if jsonb_typeof(scope) is distinct from 'object' or v_level is null
    or v_level not in ('nrw', 'regbez', 'kreis', 'gemeinde', 'school') then
    raise exception 'scope.level must be nrw, regbez, kreis, gemeinde or school' using errcode = '22023';
  end if;
  v_source := public.resolve_source(scope);
  select * into q from public.questions where id = question_id;
  if not found or q.type <> 'choice' then
    return null;
  end if;

  with dist as (
    select a.response_id, a.choice
    from public.answers a
    join public.responses r on r.id = a.response_id
    join public.schools s on s.id = r.school_id
    where not s.is_test and a.question_id = q.id
      and r.source_id = v_source
      and r.wave_id = choice_distribution.wave_id
      and cardinality(a.choice) > 0
      -- schoolInScope(): NRW only with id = null.
      and case v_level
        when 'nrw' then v_id is null
        when 'school' then s.id = v_id
        when 'kreis' then s.kreis_id = v_id
        when 'gemeinde' then s.gemeinde_id = v_id
        else left(s.kreis_id, 3) = v_id
      end
  ),
  options as (
    select
      x.opt ->> 'value' as value,
      x.ord,
      (select count(distinct d.response_id) from dist d where (x.opt ->> 'value') = any (d.choice)) as cnt
    from jsonb_array_elements(q.options) with ordinality as x (opt, ord)
  )
  select
    (select count(distinct response_id) from dist),
    jsonb_build_object(
      'questionId', q.id,
      'n', (select count(distinct response_id) from dist),
      'options', coalesce(
        (
          select jsonb_agg(
            jsonb_build_object('value', o.value, 'count', case when o.cnt < 3 then null else o.cnt end)
            order by o.ord
          )
          from options o
        ),
        '[]'::jsonb
      )
    )
  into v_n, v_result;

  return case when v_n < public.k_min() then null else v_result end;
end;
$$;
